'use strict';
const $=id=>document.getElementById(id),labels={pending:'待联系',quoted:'已报价',reserved:'已预约',completed:'已完成',cancelled:'已取消'},cars={'718':'保时捷 718',x5:'宝马 X5',my:'特斯拉 Model Y',e:'奔驰 E 级',gl8:'别克 GL8','gl8-653':'别克 GL8 653','denza-d9':'腾势 D9',magotan:'大众迈腾',passat:'大众帕萨特',jetta:'大众捷达',coaster:'丰田考斯特',h7:'红旗 H7'};
let usersOffset=0,usersTotal=0,usersVersion=0;
let offset=0,total=0,current=null,timer=null,latest=null,knownTotal=null,notificationsEnabled=false,listVersion=0,detailVersion=0,month=chinaToday().slice(0,7),grouped=true,lastRecords=[],lastLoaded=0,saving=false;
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=value=>value?new Date(value*1000).toLocaleString('zh-CN',{hour12:false}):'—';
async function api(path,body){const r=await fetch(path,{credentials:'same-origin',cache:'no-store',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok){const e=new Error(data.error||'操作失败，请重试。');e.status=r.status;throw e}return data}
function lock(message=''){clearInterval(timer);timer=null;if($('mail-dialog').open)$('mail-dialog').close();$('mail-form').reset();usersVersion++;$('users-list').replaceChildren();$('users-result').textContent='';$('users-page').textContent='';$('users-filters').reset();$('users-panel').open=false;usersOffset=0;listVersion++;detailVersion++;current=null;knownTotal=null;latest=null;$('workspace').hidden=true;$('logout').hidden=true;$('login-panel').hidden=false;lastRecords=[];$('list').replaceChildren();$('detail').replaceChildren();$('calendar').replaceChildren();$('status-chart').replaceChildren();$('identity').textContent='';$('login-result').textContent=message}
async function enter(){try{const d=await api('/api/operator/me');$('identity').textContent='管理员 · '+(d.user.email||d.user.phone);$('login-panel').hidden=true;$('workspace').hidden=false;$('logout').hidden=false;await loadList();await checkNotifications();clearInterval(timer);timer=setInterval(()=>{if(!document.hidden)checkNotifications()},20000)}catch(e){lock(e.status===401?'':e.message)}}
const filterFields=['q','status','completion','dateBasis','from','to','sort','userId'];
function chinaToday(){return new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'})}
function tripStart(v){return v.startDate||v.date||v.startAt?.slice(0,10)||''}
function tripEnd(v){return v.endDate||v.endAt?.slice(0,10)||tripStart(v)}
function filtersQuery(){const f=$('filters'),q=new URLSearchParams({offset:String(offset),month});for(const key of filterFields)q.set(key,f.elements[key].value);return q}
function keepFilterURL(){const q=filtersQuery();q.delete('q');q.delete('userId');q.delete('offset');q.set('view',grouped?'grouped':'list');history.replaceState(null,'',location.pathname+'?'+q)}
function restoreFilters(){const q=new URLSearchParams(location.search),f=$('filters');for(const key of filterFields){if(key!=='q'&&key!=='userId'&&q.has(key)){const el=f.elements[key],value=q.get(key);if(el.tagName!=='SELECT'||[...el.options].some(o=>o.value===value))el.value=value}}if(/^\d{4}-\d{2}$/.test(q.get('month')||'')&&Number(q.get('month').slice(0,4))>=1&&Number(q.get('month').slice(5))>=1&&Number(q.get('month').slice(5))<=12)month=q.get('month');grouped=q.get('view')!=='list';$('view-grouped').setAttribute('aria-pressed',String(grouped));$('view-list').setAttribute('aria-pressed',String(!grouped));if(matchMedia('(max-width:700px)').matches)$('filter-panel').open=false}
function dirtyDetail(){return current&&$('followup')&&($('followup').elements.note.value!==current.note||$('followup').elements.status.value!==current.status)}
function clearDetail(){current=null;detailVersion++;$('detail').innerHTML='<div class="empty">选择一条需求，查看行程并开始跟进。</div>'}
function applyFilters(change){if(dirtyDetail()&&!confirm('有尚未保存的跟进信息，确定切换筛选吗？'))return;const f=$('filters');if(change)change(f);f.elements.to.setCustomValidity(f.elements.from.value&&f.elements.to.value&&f.elements.to.value<f.elements.from.value?'结束日期不能早于开始日期。':'');if(!f.reportValidity())return;if(f.elements.from.value)month=f.elements.from.value.slice(0,7);offset=0;clearDetail();loadList();if(innerWidth<700)$('filter-panel').open=false}
function setCompletion(value){applyFilters(f=>{f.elements.completion.value=value;f.elements.status.value=''})}
function setStatus(value){applyFilters(f=>{f.elements.status.value=value;f.elements.completion.value=''})}
function dayString(d){return d.toISOString().slice(0,10)}
function quickRange(key){applyFilters(f=>{const today=chinaToday(),d=new Date(today+'T12:00:00Z');f.elements.dateBasis.value='trip';let from='',to='';if(key==='today')from=to=today;if(key==='week'){d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));from=dayString(d);d.setUTCDate(d.getUTCDate()+6);to=dayString(d)}if(key==='month'){from=today.slice(0,7)+'-01';d.setUTCMonth(d.getUTCMonth()+1,0);to=dayString(d)}f.elements.from.value=from;f.elements.to.value=to})}
function changeMonth(delta){const d=new Date(month+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+delta);month=d.toISOString().slice(0,7);loadList()}
function renderProgress(counts){const values=Object.keys(labels).map(key=>[key,Math.max(0,Number(counts[key])||0)]),all=values.reduce((n,[,v])=>n+v,0);$('stat-total').textContent=all;$('stat-total-note').textContent='含已取消 '+(counts.cancelled||0)+' 条';document.querySelectorAll('[data-completion]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.completion===$('filters').elements.completion.value&&!$('filters').elements.status.value)));$('stat-open').textContent=(counts.pending||0)+(counts.quoted||0)+(counts.reserved||0);$('stat-completed').textContent=counts.completed||0;$('status-chart').innerHTML=values.map(([key,n])=>`<button class="status-line status-${key} ${$('filters').elements.status.value===key?'selected':''}" data-status="${key}"><span>${labels[key]}</span><span class="bar-track" aria-hidden="true"><i style="width:${all?n/all*100:0}%"></i></span><strong>${n}<small> 条</small></strong></button>`).join('');$('status-chart').querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>setStatus(b.dataset.status))}
function renderCalendar(data){const f=$('filters'),first=new Date(data.month+'-01T12:00:00Z'),pad=(first.getUTCDay()+6)%7;$('month-label').textContent=data.month.replace('-','年')+'月';$('calendar').innerHTML=Array.from({length:pad},()=>'<span class="calendar-pad" aria-hidden="true"></span>').join('')+data.calendar.map(v=>{const selected=f.elements.dateBasis.value==='trip'&&f.elements.from.value&&f.elements.to.value&&v.date>=f.elements.from.value&&v.date<=f.elements.to.value;return `<button class="calendar-day ${v.count?'busy':''} ${selected?'selected':''} ${v.date===data.today?'today':''}" data-day="${v.date}" aria-label="${v.date}，${v.count}条用车需求" aria-pressed="${!!selected}" ${v.date===data.today?'aria-current="date"':''}><span>${Number(v.date.slice(-2))}</span><small>${v.count?v.count+'条':'—'}</small></button>`}).join('');$('calendar').querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>applyFilters(f=>{f.elements.dateBasis.value='trip';f.elements.from.value=b.dataset.day;f.elements.to.value=b.dataset.day}));$('calendar-note').textContent='日历按当前筛选统计用车需求，多日行程在期间每天计入；不是车辆档期。'+(data.undated?'另有 '+data.undated+' 条未记录用车日期。':'');$('updated-at').textContent='更新于 '+date(data.updatedAt)+' · 页面打开时每分钟刷新概览。'}
function requestCard(v){const deadline=tripEnd(v),late=deadline&&deadline<chinaToday()&&!['completed','cancelled'].includes(v.status);return `<button class="request ${current?.id===v.id?'active':''}" data-id="${escape(v.id)}"><div class="request-top"><strong>${v.unread?'<i class="unread" aria-label="未读"></i>':''}${escape(v.name)}</strong><span class="badge status-${escape(v.status)}">${labels[v.status]||labels.pending}</span></div><p>${escape(v.service)} · ${escape(cars[v.car]||'待推荐车型')}</p><p>${escape(v.city)} · ${escape(tripStart(v)||'用车日期未记录')} ${tripEnd(v)?'→ '+escape(tripEnd(v)):''}</p><p>${escape(v.people)} 人 · ${escape(v.bags)} 件行李</p>${late?'<p class="overdue">行程日期已过，待核对是否完成</p>':''}<p class="small">提交 ${date(v.created)} · ${escape(v.id)}</p></button>`}
function renderRequests(records){lastRecords=records;if(!records.length)$('list').innerHTML='<div class="empty">没有符合筛选的需求。可放宽日期、状态或关键词。</div>';else if(grouped){const groups=new Map();for(const v of records){const key=$('filters').elements.dateBasis.value==='submitted'?new Date(v.created*1000).toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'}):tripStart(v)||'日期未记录';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(v)}$('list').innerHTML=[...groups].map(([key,items])=>`<div class="date-group-heading"><h3>${escape(key)}</h3><span>${items.length} 条 · 当前页</span></div>${items.map(requestCard).join('')}`).join('')}else $('list').innerHTML=records.map(requestCard).join('');$('list').querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>openDetail(b.dataset.id));$('prev').disabled=offset===0;$('next').disabled=offset+50>=total;$('page-label').textContent=total?'第 '+(offset+1)+'–'+Math.min(offset+50,total)+' 条 / '+total+' 条':'0 条'}
function filterHint(){const f=$('filters'),dateLabel=f.elements.dateBasis.value==='trip'?'用车期间':'提交日期',range=f.elements.from.value||f.elements.to.value?`${f.elements.from.value||'不限'} 至 ${f.elements.to.value||'不限'}`:'不限日期',completion={open:'未完成',completed:'已完成',cancelled:'已取消'}[f.elements.completion.value]||'全部完成情况';$('filter-hint').textContent=dateLabel+' · '+range+' · '+(labels[f.elements.status.value]||completion)+(f.elements.q.value?' · 已使用关键词':'')+(f.elements.userId.value?' · 当前选中账号':'')}
async function loadList(){const version=++listVersion,query=filtersQuery();const results=await Promise.allSettled([api('/api/operator/inquiries?'+query),api('/api/operator/summary?'+query)]);if(version!==listVersion)return;for(const r of results){if(r.status==='rejected'&&[401,403].includes(r.reason.status)){lock(r.reason.message);return}}if(results[0].status==='rejected'){$('result').textContent='更新失败：'+results[0].reason.message+'；保留上次数据。';$('result').className='error';$('updated-at').textContent='连接暂不可用，以下为上次数据。';return}const d=results[0].value;total=d.total;$('result').textContent='找到 '+total+' 条需求 · '+(grouped?'按日期分组（当前页）':'列表')+ ' · 每页最多50条';$('result').className='';renderProgress(d.counts);renderRequests(d.inquiries);filterHint();if(results[1].status==='fulfilled')renderCalendar(results[1].value);else $('calendar-note').textContent='日历暂时无法更新，保留上次结果；需求列表仍可使用。';lastLoaded=Date.now();keepFilterURL()}

async function openDetail(id){if(current&&$('followup')&&($('followup').elements.note.value!==current.note||$('followup').elements.status.value!==current.status)&&!confirm('有尚未保存的备注，确定切换需求吗？'))return;const version=++detailVersion;try{const d=await api('/api/operator/detail?id='+encodeURIComponent(id));if(version!==detailVersion)return;current=d.inquiry;const v=current,rows=[['电话',v.phone],['微信',v.wechat],['服务',v.service],['车型',cars[v.car]||'请为我推荐'],['服务城市',v.city],['取车 / 上车',v.pickup],['还车 / 下车',v.returnAt],['目的地',v.destination],['开始',v.startAt?.replace('T',' ')],['结束',v.endAt?.replace('T',' ')],['估算租期',inquiryDurationLabel(v)],['人数 / 行李',v.people+' 人 / '+v.bags+' 件'],['提交时间',date(v.created)]];$('detail').innerHTML=`<p class="eyebrow">ENQUIRY DETAIL</p><div class="detail-heading"><h2>${escape(v.name)}</h2><button type="button" id="close-detail" aria-label="关闭需求详情">关闭</button></div><p class="muted small">${escape(v.id)}</p><dl>${rows.map(([k,val])=>`<dt>${escape(k)}</dt><dd>${escape(val||'—')}</dd>`).join('')}</dl><form id="followup"><label>跟进状态<select name="status">${Object.entries(labels).map(([key,label])=>`<option value="${key}" ${key===v.status?'selected':''}>${label}</option>`).join('')}</select></label><label>跟进备注<textarea name="note" maxlength="2000" placeholder="记录联系结果、报价情况和待办事项">${escape(v.note)}</textarea></label><p class="muted small">备注仅管理员可见。状态记录不自动发送报价、锁车或收款。</p><div class="followup-actions"><button type="submit" class="primary">保存跟进</button>${v.status==='completed'?'':'<button type="button" id="mark-completed">标记为已完成</button>'}</div><p id="save-result" role="status"></p></form><h3>跟进记录</h3>${d.history.length?d.history.map(h=>`<div class="history"><span class="badge">${labels[h.status]}</span><span class="muted small"> ${date(h.created)}</span><p>${escape(h.note||'无备注')}</p></div>`).join(''):'<p class="muted">尚无跟进记录。</p>'}`;$('followup').onsubmit=saveFollowup;$('close-detail').onclick=()=>{if(!dirtyDetail()||confirm('放弃未保存的跟进信息？')){clearDetail();renderRequests(lastRecords)}};if($('mark-completed'))$('mark-completed').onclick=()=>{$('followup').elements.status.value='completed';$('followup').requestSubmit()};await api('/api/operator/seen',{id});await loadList();await checkNotifications();if(window.innerWidth<850)$('detail').scrollIntoView({behavior:'smooth',block:'start'})}catch(e){if(e.status===401||e.status===403)lock(e.message);else{$('result').textContent=e.message;$('result').className='error'}}}
async function saveFollowup(e){e.preventDefault();if(saving)return;saving=true;const form=e.target,button=form.querySelector('button'),record=current;button.disabled=true;try{const data=await api('/api/operator/update',{id:record.id,status:form.elements.status.value,note:form.elements.note.value,revision:record.revision});record.revision=data.revision;record.note=form.elements.note.value.trim();form.elements.note.value=record.note;record.status=form.elements.status.value;if(current!==record){await loadList();return}await openDetail(record.id);$('save-result').textContent='已保存';$('save-result').className='success'}catch(err){if(err.status===401||err.status===403)lock(err.message);else{$('save-result').textContent=err.message;$('save-result').className='error'}}finally{saving=false;button.disabled=false}}
async function checkNotifications(){try{const d=await api('/api/operator/notifications');if(knownTotal!==null&&d.total>knownTotal){if(notificationsEnabled&&'Notification'in window&&Notification.permission==='granted'){try{new Notification('YC 有新的用车需求',{body:'请登录管理后台查看并联系客户。'})}catch{}}await loadList()}if(Date.now()-lastLoaded>60000&&!$('workspace').hidden)await loadList();latest=d.latestId;knownTotal=d.total;$('email-status').textContent=d.email?.configured?'邮件提醒：'+d.email.pending+' 封待发送，'+d.email.sent+' 封已提交邮件服务。':'邮件提醒尚未配置 SMTP 授权码；需求会保存在后台，通知留在发送队列。';$('notice').textContent=d.unread?'你有 '+d.unread+' 条未读需求，打开需求详情即可标记已读。':'需求已读完，新的提交会在这里提醒。'}catch(e){if(e.status===401||e.status===403)lock(e.message);else $('notice').textContent='新需求检查暂时失败，请刷新重试。'}}
$('login-form').onsubmit=async e=>{e.preventDefault();const form=e.target,b=form.querySelector('button');b.disabled=true;$('login-result').textContent='';try{await api('/api/auth/login',{email:form.elements.email.value,password:form.elements.password.value});form.elements.password.value='';await enter()}catch(err){$('login-result').textContent=err.message}finally{b.disabled=false}};
$('logout').onclick=async()=>{try{await api('/api/auth/logout',{});lock('已退出登录。')}catch(e){$('result').textContent=e.message}};
$('filters').onsubmit=e=>{e.preventDefault();applyFilters()};
$('filters').elements.completion.onchange=()=>{$('filters').elements.status.value=''};$('filters').elements.status.onchange=()=>{$('filters').elements.completion.value=''};
$('filters').elements.from.onchange=()=>{$('filters').elements.to.setCustomValidity('')};$('filters').elements.to.onchange=()=>{$('filters').elements.to.setCustomValidity('')};
document.querySelectorAll('[data-completion]').forEach(b=>b.onclick=()=>setCompletion(b.dataset.completion));document.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>quickRange(b.dataset.range));
$('reset-filters').onclick=()=>applyFilters(f=>{f.reset();month=chinaToday().slice(0,7)});
$('month-prev').onclick=()=>changeMonth(-1);$('month-next').onclick=()=>changeMonth(1);
$('view-grouped').onclick=()=>{grouped=true;$('view-grouped').setAttribute('aria-pressed','true');$('view-list').setAttribute('aria-pressed','false');renderRequests(lastRecords);keepFilterURL()};
$('view-list').onclick=()=>{grouped=false;$('view-grouped').setAttribute('aria-pressed','false');$('view-list').setAttribute('aria-pressed','true');renderRequests(lastRecords);keepFilterURL()};
$('prev').onclick=()=>{offset=Math.max(0,offset-50);loadList()};$('next').onclick=()=>{offset+=50;loadList()};$('refresh').onclick=async()=>{await loadList();await checkNotifications()};
$('enable-notifications').onclick=async()=>{if(!('Notification'in window)){$('notice').textContent='此浏览器不支持系统通知，后台未读提醒仍然可用。';return}try{notificationsEnabled=(await Notification.requestPermission())==='granted';$('enable-notifications').textContent=notificationsEnabled?'浏览器提醒已启用':'浏览器提醒未授权'}catch{$('notice').textContent='无法启用浏览器提醒，后台未读提醒仍然可用。'}};
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!$('workspace').hidden)checkNotifications()});window.addEventListener('beforeunload',e=>{if(current&&$('followup')&&($('followup').elements.note.value!==current.note||$('followup').elements.status.value!==current.status)){e.preventDefault();e.returnValue=''}});restoreFilters();enter();

$('show-password').onclick=()=>{const input=$('login-form').elements.password,visible=input.type==='password';input.type=visible?'text':'password';$('show-password').textContent=visible?'隐藏密码':'显示密码';$('show-password').setAttribute('aria-pressed',String(visible))};

$('mail-settings').onclick=()=>{$('mail-result').textContent='';$('mail-dialog').showModal()};$('close-mail').onclick=()=>{$('mail-dialog').close();$('mail-form').reset()};
$('mail-form').onsubmit=async e=>{e.preventDefault();const form=e.target,b=form.querySelector('button[type="submit"]');b.disabled=true;try{const data=await api('/api/operator/mail-config',{authorizationCode:form.elements.authorizationCode.value.trim(),sendTest:form.elements.sendTest.checked});form.reset();$('mail-result').textContent=data.testQueued?'配置已保存，测试提醒已进入发送队列。请检查收件箱和垃圾邮件。':'配置已保存，新需求将进入邮件发送队列。';await checkNotifications()}catch(err){if(err.status===401||err.status===403)lock(err.message);else $('mail-result').textContent=err.message}finally{b.disabled=false}};

window.addEventListener('pageshow',event=>{if(event.persisted){lock();enter()}});

function inquiryDurationLabel(v){
 const start=v.startAt||(v.startDate&&v.startTime?v.startDate+'T'+v.startTime:''),end=v.endAt||(v.endDate&&v.endTime?v.endDate+'T'+v.endTime:'');
 const instant=s=>s&&s.includes('T')?Date.parse(/[Zz]|[+-]\d{2}:?\d{2}$/.test(s)?s:s+'+08:00'):NaN;
 const duration=Math.ceil((instant(end)-instant(start))/86400000);
 return Number.isFinite(duration)&&duration>0?duration+' 天（按24小时估算）':(v.durationDays?v.durationDays+' 天（原记录，时刻不完整）':'待确认');
}

async function loadUsers(){
 const version=++usersVersion,f=$('users-filters'),query=new URLSearchParams({offset:String(usersOffset)});
 for(const key of ['q','from','to'])query.set(key,f.elements[key].value);
 $('users-result').textContent='正在读取账号…';
 try{const data=await api('/api/operator/users?'+query);if(version!==usersVersion)return;usersTotal=data.total;
 $('users-result').textContent='找到 '+data.total+' 个注册账号';
 $('users-list').innerHTML=data.users.length?data.users.map(u=>`<article class="user-card"><div><h3>${escape(u.name)}</h3><p>${escape(u.phone||u.email)}</p><p class="muted small">注册 ${escape(date(u.created))} · ${u.isOperator?'管理员':'普通账号'} · ${u.contactVerified?'邮箱已验证':'联系方式未验证'}</p></div><button type="button" data-user="${escape(u.id)}">查看关联需求 · ${u.inquiryCount}</button></article>`).join(''):'<p class="muted">没有符合条件的账号。</p>';
 $('users-prev').disabled=usersOffset===0;$('users-next').disabled=usersOffset+50>=usersTotal;$('users-page').textContent=data.total?(usersOffset+1)+'–'+Math.min(usersOffset+50,data.total)+' / '+data.total:'0 个账号';
 $('users-list').querySelectorAll('[data-user]').forEach(button=>button.onclick=()=>{applyFilters(f=>{f.reset();f.elements.userId.value=button.dataset.user});$('records').scrollIntoView({block:'start',behavior:'smooth'})});
 }catch(e){if(version!==usersVersion)return;if(e.status===401||e.status===403)lock(e.message);else{$('users-list').replaceChildren();$('users-result').textContent=e.message;$('users-prev').disabled=true;$('users-next').disabled=true}}
}
$('users-panel').addEventListener('toggle',()=>{if($('users-panel').open)loadUsers()});
$('users-filters').onsubmit=e=>{e.preventDefault();const f=e.target;f.elements.to.setCustomValidity(f.elements.from.value&&f.elements.to.value&&f.elements.to.value<f.elements.from.value?'结束日期不能早于开始日期。':'');if(f.reportValidity()){usersOffset=0;loadUsers()}};
$('users-reset').onclick=()=>{$('users-filters').reset();$('users-filters').elements.to.setCustomValidity('');usersOffset=0;loadUsers()};
$('users-prev').onclick=()=>{usersOffset=Math.max(0,usersOffset-50);loadUsers()};$('users-next').onclick=()=>{usersOffset+=50;loadUsers()};
